 printf(" \n");
}
return 0;
}
</code></pre>

What is printed by the following ANSI C program?<pre><code>#include &lt;stdio.h&gt;
int main(int argc, char *argv[]){ 
 char a = 'P';
 char b = 'x';
 char c = (a  &  b) + '*';
 char d = (a | b) - '-';
 char e = (a ^ b) + '+'; 
 printf("%c %c %c \n", c, d, e); 
 return 0;
}
</code></pre><br>ASCII encoding for relevant characters is given below<br><img src="/wp-content/uploads/GATE/CS/20221/q34.jpg" /><br>

